begin;
set local search_path=public,extensions;
select no_plan();
create temporary table config_fixture(id uuid);
grant all on config_fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.draft_scoped_configuration('sop',(select definition from public.config_version where id='40000000-0000-4000-8000-000000000001'),now(),null)$$,'P0001','Admin AAL2 required','Configuration import cannot bypass admin MFA');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.draft_scoped_configuration('sop','{}',now(),null)$$,'P0001','SOP stages/checkpoints required','Incomplete imported configuration is rejected');
select throws_ok($$select public.draft_scoped_configuration('sop',(select jsonb_set(definition,'{checkpoints,1,interval_hours}','0') from public.config_version where id='40000000-0000-4000-8000-000000000001'),now(),null)$$,'P0001','Checkpoint interval must be positive','Invalid recurring timing is rejected');
insert into config_fixture select public.draft_scoped_configuration('sop',(select definition from public.config_version where id='40000000-0000-4000-8000-000000000001'),now()+interval '1 day','10000000-0000-4000-8000-000000000002');
select is((select status from public.config_version where id=(select id from config_fixture)),'draft','Imported documents are always drafts');
select is((select cooperative_id::text from public.config_version where id=(select id from config_fixture)),'10000000-0000-4000-8000-000000000002','Admin can draft for another cooperative');
select is((select config_version_id::text from public.lot where id='60000000-0000-4000-8000-000000000002'),'40000000-0000-4000-8000-000000000001','Existing batches retain their original SOP');
select throws_ok($$select public.approve_configuration((select id from config_fixture),gen_random_uuid())$$,'P0001','Food-Safety Lead AAL2 required','Admin cannot approve their imported draft');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.approve_configuration((select id from config_fixture),public.pin_signoff('2468','30000000-0000-4000-8000-000000000001','config',(select id from config_fixture)))$$,'Separate Food-Safety Lead approves scoped draft with PIN');
select ok(exists(select 1 from public.training_module where config_version_id=(select id from config_fixture) and required),'Scoped approval inherits required training from the effective previous SOP');
select * from finish();
rollback;
